// EWGaugeAct returns -i * G * Psi in real components, where G is the Hermitian
// 2x2 gauge matrix that the covariant derivative is built from:
//
//	G = g W^a T^a + g' Y_Phi B,   T^a = sigma^a / 2
//	  = [[ du, or + i oi ], [ or - i oi, dd ]]
//	du = (g/2) W3 + g' Y B      or = (g/2) W1
//	dd = -(g/2) W3 + g' Y B     oi = -(g/2) W2
//
// The opposite sign of W3 on the diagonal is T^3 = +-1/2: why the upper and
// lower components feel W3 oppositely but B identically. The combination
// annihilating the vacuum is Q = T^3 + Y, the one massless direction.
//
// This one operation is the entire gauge coupling: D_mu Psi = d_mu Psi +
// EWGaugeAct(W_mu, B_mu, Psi), and the covariant Laplacian composes from it.
// Psi is the doublet as four reals, (X + iY, Z + iW) = sqrt(2) Phi.
func EWGaugeAct(w1, w2, w3, b float32, psi math32.Vector4) math32.Vector4 {
	return EWGaugeActY(w1, w2, w3, b, YPhi, psi)
}

// EWGaugeActY is [EWGaugeAct] for a doublet of any weak hypercharge: the
// Higgs has Y = +1/2, the lepton doublet Y = -1/2, and that sign is the whole
// difference between a field the photon ignores and one it does not.
func EWGaugeActY(w1, w2, w3, b, yhyp float32, psi math32.Vector4) math32.Vector4 {
	hg := 0.5 * Params[0].GW
	gy := Params[0].GpW * yhyp
	du := hg*w3 + gy*b
	dd := -hg*w3 + gy*b
	or := hg * w1
	oi := -hg * w2
	var o math32.Vector4
	o.X = du*psi.Y + or*psi.W + oi*psi.Z
	o.Y = -(du*psi.X + or*psi.Z - oi*psi.W)
	o.Z = or*psi.Y - oi*psi.X + dd*psi.W
	o.W = -(or*psi.X + oi*psi.Y + dd*psi.Z)
	return o
}

// EWGaugeMul returns G_mu Psi itself rather than the -i G_mu Psi that a
// covariant derivative wants. The second-order Higgs equation only ever needs
// the covariant derivative, but the first-order lepton equation has to put the
// potential inside its own sigma contraction first, and multiply by i at the
// end of all of it.
func EWGaugeMul(w1, w2, w3, b, yhyp float32, psi math32.Vector4) math32.Vector4 {
	o := EWGaugeActY(w1, w2, w3, b, yhyp, psi)
	return math32.Vec4(-o.Y, o.X, -o.W, o.Z) // times i
}

// EWSpinBilinear returns psi^dag S chi for two 2-spinors, each given as its
// pair of complex components, where S is the identity at mu = 0 and
// sigma^x, sigma^y, sigma^z at mu = 1, 2, 3. The result is complex.
//
// These four are every bilinear a Weyl current is built from: the identity one
// is the density and the three sigma ones are the flux.
func EWSpinBilinear(mu int32, p1, p2, c1, c2 math32.Vector2) math32.Vector2 {
	// conj(p) * c for each component
	a1 := math32.Vec2(p1.X*c1.X+p1.Y*c1.Y, p1.X*c1.Y-p1.Y*c1.X)
	a2 := math32.Vec2(p2.X*c2.X+p2.Y*c2.Y, p2.X*c2.Y-p2.Y*c2.X)
	x1 := math32.Vec2(p1.X*c2.X+p1.Y*c2.Y, p1.X*c2.Y-p1.Y*c2.X)
	x2 := math32.Vec2(p2.X*c1.X+p2.Y*c1.Y, p2.X*c1.Y-p2.Y*c1.X)
	if mu == 1 {
		return math32.Vec2(x1.X+x2.X, x1.Y+x2.Y)
	}
	if mu == 2 { // -i x1 + i x2
		return math32.Vec2(x1.Y-x2.Y, x2.X-x1.X)
	}
	if mu == 3 {
		return math32.Vec2(a1.X-a2.X, a1.Y-a2.Y)
	}
	return math32.Vec2(a1.X+a2.X, a1.Y+a2.Y)
}

// EWLeptonCurrent returns the four gauge currents the leptons put into the
// gauge fields at spacetime index mu, in the same (W^1, W^2, W^3, B) layout
// EWCurrent uses:
//
//	j^a_mu = g  Lbar gamma_mu T^a L                     (a = 1,2,3)
//	j^Y_mu = g' [ Y_L Lbar gamma_mu L + Y_R eRbar gamma_mu e_R ]
//
// A left-handed Weyl field has four-current (psi^dag psi, -psi^dag sigma psi)
// and a right-handed one (psi^dag psi, +psi^dag sigma psi): they stream
// opposite ways, which is what chirality is. So a massive electron's net flux
// is |e_L|^2 - |e_R|^2 against a density of |e_L|^2 + |e_R|^2, and their ratio
// is the group velocity -- the same relation the free Weyl equation gives.
//
// Projecting onto the photon, sinTheta_W j^3 + cosTheta_W j^Y, the
// hypercharges collapse the whole thing to -e(|e_L|^2 + |e_R|^2) with nothing
// at all from the neutrino. The charge the leptons SOURCE is the same charge
// they FEEL, and neither was written down.
func EWLeptonCurrent(x, y, z, prv, mu int32) math32.Vector4 {
	n1 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWNu1a), int(prv)), State.Value(int(z), int(y), int(x), int(EWNu1b), int(prv)))
	n2 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWNu2a), int(prv)), State.Value(int(z), int(y), int(x), int(EWNu2b), int(prv)))
	l1 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWEL1a), int(prv)), State.Value(int(z), int(y), int(x), int(EWEL1b), int(prv)))
	l2 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWEL2a), int(prv)), State.Value(int(z), int(y), int(x), int(EWEL2b), int(prv)))
	r1 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWER1a), int(prv)), State.Value(int(z), int(y), int(x), int(EWER1b), int(prv)))
	r2 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWER2a), int(prv)), State.Value(int(z), int(y), int(x), int(EWER2b), int(prv)))

	nn := EWSpinBilinear(mu, n1, n2, n1, n2)
	ee := EWSpinBilinear(mu, l1, l2, l1, l2)
	ne := EWSpinBilinear(mu, n1, n2, l1, l2)
	rr := EWSpinBilinear(mu, r1, r2, r1, r2)

	// the flux of a left-handed field runs against its spin; a right-handed
	// one runs with it. At mu = 0 both are just the density.
	sl := float32(1)
	if mu > 0 {
		sl = -1
	}
	hg := 0.5 * Params[0].GW
	gp := Params[0].GpW
	var j math32.Vector4
	j.X = sl * 2 * hg * ne.X // L^dag tau^1 L / 2 = Re(nu^dag e)
	j.Y = sl * 2 * hg * ne.Y // L^dag tau^2 L / 2 = Im(nu^dag e)
	j.Z = sl * hg * (nn.X - ee.X)
	j.W = gp * (sl*YLep*(nn.X+ee.X) + YER*rr.X)
	return j
}

// EWCurrent returns the four gauge currents that a doublet Psi with covariant
// derivative d = D_mu Psi puts into the gauge fields at spacetime index mu:
//
//	X,Y,Z = j^a_mu = 2 g  Im[Phi^dag T^a D_mu Phi]   (a = 1,2,3, sourcing W^a)
//	W     = j^Y_mu = 2 g' Y Im[Phi^dag D_mu Phi]     (sourcing B)
//
// with Phi = Psi/sqrt(2) folding one factor of 1/2 into each expression.
//
// NOTHING in this kernel contains a gauge boson mass term. The masses arise
// because Psi is non-zero everywhere: evaluated at the vacuum this current
// reduces to exactly -m^2 times the gauge field itself, uniformly and
// permanently. That feedback is the Higgs mechanism.
func EWCurrent(psi, d math32.Vector4) math32.Vector4 {
	hg := 0.5 * Params[0].GW
	gy := Params[0].GpW * YPhi
	var j math32.Vector4
	j.X = hg * ((psi.X*d.W - psi.Y*d.Z) + (psi.Z*d.Y - psi.W*d.X))
	j.Y = hg * (-(psi.X*d.Z + psi.Y*d.W) + (psi.Z*d.X + psi.W*d.Y))
	j.Z = hg * ((psi.X*d.Y - psi.Y*d.X) - (psi.Z*d.W - psi.W*d.Z))
	j.W = gy * ((psi.X*d.Y - psi.Y*d.X) + (psi.Z*d.W - psi.W*d.Z))
	return j
}

// EWDiv returns the lattice divergence of a 3-vector gauge potential whose
// X, Y, Z components are the three consecutive state variables at vX.
func EWDiv(x, y, z, vX, tidx int32) float32 {
	gx := Gradient10(x, y, z, vX, tidx)
	gy := Gradient10(x, y, z, vX+1, tidx)
	gz := Gradient10(x, y, z, vX+2, tidx)
	return gx.X + gy.Y + gz.Z
}

// EWCrossUp returns sum_mu (A^mu x B_mu), the contraction of an UPPER with a
// LOWER spacetime index. No metric signs: all four terms add.
//
// Every eps^{abc} in the Yang-Mills equation is a cross product in adjoint
// space, since eps^{abc} X^b Y^c = (X x Y)^a. Writing the self-coupling this
// way turns a triple-index mess into four cross products.
func EWCrossUp(a0, ax, ay, az, b0, bx, by, bz math32.Vector3) math32.Vector3 {
	r := slmath.Cross3(a0, b0)
	r = r.Add(slmath.Cross3(ax, bx))
	r = r.Add(slmath.Cross3(ay, by))
	r = r.Add(slmath.Cross3(az, bz))
	return r
}

// EWCrossLor returns sum_mu (A_mu x B^mu) where BOTH carry the same index
// position, so the (+,-,-,-) metric appears: time adds, space subtracts.
func EWCrossLor(a0, ax, ay, az, b0, bx, by, bz math32.Vector3) math32.Vector3 {
	r := slmath.Cross3(a0, b0)
	r = r.Sub(slmath.Cross3(ax, bx))
	r = r.Sub(slmath.Cross3(ay, by))
	r = r.Sub(slmath.Cross3(az, bz))
	return r
}

// EWBorisRot3 is the Boris rotation for an adjoint 3-vector velocity: the
// EXACT, norm-preserving update for dv/dt = v x Omega over one unit step.
//
//	t = Omega/2 ;  v' = v + v x t ;  v+ = v + v' x (2t / (1 + |t|^2))
//
// The two half-turns compose into a true rotation, which is the whole point:
// the velocity-dependent gauge force does not change |v|, and an explicit
// update gets that wrong at O(Omega^2) EVERY step, which is what makes the
// rotating-frame system blow up.
func EWBorisRot3(v, om math32.Vector3) math32.Vector3 {
	t := om.MulScalar(0.5)
	vp := v.Add(slmath.Cross3(v, t))
	s := t.MulScalar(2.0 / (1.0 + slmath.LengthSquared3(t)))
	return v.Add(slmath.Cross3(vp, s))
}

// EWBorisPhase rotates the Higgs velocity by exp(i theta G_0), the exact
// solution of the velocity-dependent part of the Higgs equation,
//
//	dv/dt = -2c (-i G_0) v = 2ic G_0 v   ->   v(1) = exp(2ic G_0) v(0)
//
// so theta = 2c. For the 2x2 Hermitian gauge matrix this has a closed form:
// splitting G_0 = alpha I + m.sigma, with
//
//	m = (g/2) (W^1_0, W^2_0, W^3_0)   and   alpha = g' Y_Phi B_0
//
// the exponential is
//
//	exp(i theta alpha) * (cos(theta |m|) I + i sin(theta |m|) mhat.sigma)
//
// The SU(2) part turns the doublet, the U(1) part is an overall phase: the
// parallel transport the connection generates.
func EWBorisPhase(w1, w2, w3, b, theta float32, v math32.Vector4) math32.Vector4 {
	hg := 0.5 * Params[0].GW
	m := math32.Vec3(hg*w1, hg*w2, hg*w3)
	al := Params[0].GpW * YPhi * b
	mag := slmath.Length3(m)
	var nx, ny, nz, sn float32
	if mag > 1.0e-12 {
		nx = m.X / mag
		ny = m.Y / mag
		nz = m.Z / mag
		sn = math32.Sin(theta * mag)
	}
	cs := math32.Cos(theta * mag)
	// P = (mhat.sigma) Psi, in real components
	p1r := nz*v.X + nx*v.Z + ny*v.W
	p1i := nz*v.Y + nx*v.W - ny*v.Z
	p2r := nx*v.X - ny*v.Y - nz*v.Z
	p2i := nx*v.Y + ny*v.X - nz*v.W
	// Q = cos Psi + i sin P
	q1r := cs*v.X - sn*p1i
	q1i := cs*v.Y + sn*p1r
	q2r := cs*v.Z - sn*p2i
	q2i := cs*v.W + sn*p2r
	// overall U(1) phase exp(i theta alpha)
	ca := math32.Cos(theta * al)
	sa := math32.Sin(theta * al)
	return math32.Vec4(ca*q1r-sa*q1i, ca*q1i+sa*q1r, ca*q2r-sa*q2i, ca*q2i+sa*q2r)
}

// ElectroweakKernel is the kernel for the SU(2)_L x U(1)_Y electroweak model:
// the Higgs doublet coupled to the three W^a gauge fields and the B field.
// Only supports 3D.
//
// # Fields
//
// The Higgs doublet is four real fields,
//
//	Phi = (1/sqrt2) ( hsCa + i hsCb , hs0a + i hs0b )^T
//
// so mag = hsCa^2 + hsCb^2 + hs0a^2 + hs0b^2 = 2 Phi^dag Phi. The vacuum
// <Phi> = (0, v/sqrt2)^T is hs0a = v, rest zero. It MUST be the neutral
// (lower) component, or Q = T^3 + Y does not annihilate the vacuum and the
// photon gains mass.
//
// Each gauge field is a four-potential (0, X, Y, Z) with its own velocity, as
// in MaxwellKernel, evolved in Lorenz gauge:
//
//	box W^a_mu = j^a_mu,    box B_mu = j^Y_mu
//
// # Units
//
// Inverse cube units (1/cube) throughout, which is what makes g, g' and lambda
// the bare dimensionless SM numbers (see Units.Update).
//
// # Yang-Mills self-coupling
//
// Enabled by Params.YangMills. With a Feynman-type gauge-fixing term (xi = 1)
// cancelling the -d^nu(d.W) piece, the non-abelian equation of motion is
//
//	box W^a_nu = j^a_nu
//	             + g eps^abc (d.W^b) W^c_nu                  [divergence]
//	             + 2g eps^abc W^{b mu} d_mu W^c_nu           [transport]
//	             - g eps^abc W^b_mu d^nu W^{c mu}            [transpose]
//	             - g^2 eps^abc eps^cde (W^b.W^d) W^e_nu      [quartic]
//
// The three CUBIC signs are fixed by requiring force = -dU/dphi for the energy
// with F^a_jk = d_j W^a_k - d_k W^a_j + g eps^abc W^b_j W^c_k; see
// TestElectroweakForceIsEnergyGradient. The pure-gauge test cannot fix them:
// flipping the signs also reverses the rotation sense it predicts, so it
// passes either way. The quartic sign is independent, checked on uniform
// fields.
//
// The divergence term is kept, not dropped: unlike the abelian case d.W^a = 0
// is NOT preserved by the non-abelian evolution, so it cannot be imposed.
//
// All four terms are quadratic or cubic in W, so they vanish at linear order
// and leave the spectrum unchanged. What they add is the W self-interaction:
// the difference between SU(2) and three copies of U(1).
func ElectroweakKernel(i uint32) { //gosl:kernel
	ctx := GetCtx(0)
	var x, y, z int32
	ok := ctx.StateCoords(i, &x, &y, &z)
	if !ok {
		return
	}
	cur := ctx.CurState
	prv := ctx.PrevState()
	csq := Params[0].CSq
	oc := 1.0 / Params[0].C
	boris := Params[0].Boris.IsTrue()
	musq := Params[0].HiggsMuSq
	lambda := Params[0].HiggsLambda

	// ---- Higgs doublet and its velocity ----------------------------------
	psi := math32.Vec4(State.Value(int(z), int(y), int(x), int(EWHsCa), int(prv)), State.Value(int(z), int(y), int(x), int(EWHsCb), int(prv)),
		State.Value(int(z), int(y), int(x), int(EWHs0a), int(prv)), State.Value(int(z), int(y), int(x), int(EWHs0b), int(prv)))
	psv := math32.Vec4(State.Value(int(z), int(y), int(x), int(EWHvCa), int(prv)), State.Value(int(z), int(y), int(x), int(EWHvCb), int(prv)),
		State.Value(int(z), int(y), int(x), int(EWHv0a), int(prv)), State.Value(int(z), int(y), int(x), int(EWHv0b), int(prv)))

	// ---- gauge potentials, per spacetime index ---------------------------
	w10 := State.Value(int(z), int(y), int(x), int(EWW10s), int(prv))
	w1x := State.Value(int(z), int(y), int(x), int(EWW1Xs), int(prv))
	w1y := State.Value(int(z), int(y), int(x), int(EWW1Ys), int(prv))
	w1z := State.Value(int(z), int(y), int(x), int(EWW1Zs), int(prv))
	w20 := State.Value(int(z), int(y), int(x), int(EWW20s), int(prv))
	w2x := State.Value(int(z), int(y), int(x), int(EWW2Xs), int(prv))
	w2y := State.Value(int(z), int(y), int(x), int(EWW2Ys), int(prv))
	w2z := State.Value(int(z), int(y), int(x), int(EWW2Zs), int(prv))
	w30 := State.Value(int(z), int(y), int(x), int(EWW30s), int(prv))
	w3x := State.Value(int(z), int(y), int(x), int(EWW3Xs), int(prv))
	w3y := State.Value(int(z), int(y), int(x), int(EWW3Ys), int(prv))
	w3z := State.Value(int(z), int(y), int(x), int(EWW3Zs), int(prv))
	b0 := State.Value(int(z), int(y), int(x), int(EWB0s), int(prv))
	bx := State.Value(int(z), int(y), int(x), int(EWBXs), int(prv))
	by := State.Value(int(z), int(y), int(x), int(EWBYs), int(prv))
	bz := State.Value(int(z), int(y), int(x), int(EWBZs), int(prv))

	// ---- ordinary gradients of the four Higgs components -----------------
	gCa := Gradient10(x, y, z, int32(EWHsCa), prv)
	gCb := Gradient10(x, y, z, int32(EWHsCb), prv)
	g0a := Gradient10(x, y, z, int32(EWHs0a), prv)
	g0b := Gradient10(x, y, z, int32(EWHs0b), prv)

	dxp := math32.Vec4(gCa.X, gCb.X, g0a.X, g0b.X) // d_x Psi
	dyp := math32.Vec4(gCa.Y, gCb.Y, g0a.Y, g0b.Y)
	dzp := math32.Vec4(gCa.Z, gCb.Z, g0a.Z, g0b.Z)

	// ---- covariant derivatives D_mu Psi = d_mu Psi - i G_mu Psi ----------
	ax := EWGaugeAct(w1x, w2x, w3x, bx, psi)
	ay := EWGaugeAct(w1y, w2y, w3y, by, psi)
	az := EWGaugeAct(w1z, w2z, w3z, bz, psi)
	a0 := EWGaugeAct(w10, w20, w30, b0, psi)

	dX := dxp.Add(ax)
	dY := dyp.Add(ay)
	dZ := dzp.Add(az)
	// the time component: velocities are per step and c is cubes per step, so
	// psv/c is d_0 Psi in the same 1/cube units as the spatial gradients.
	dtp := math32.Vec4(oc*psv.X, oc*psv.Y, oc*psv.Z, oc*psv.W)
	d0 := dtp.Add(a0)

	// ---- covariant Laplacian ---------------------------------------------
	// D_j D_j Psi = d_j(D_j Psi) - i G_j (D_j Psi)
	//
	//	= lap(Psi) - i(d_j G_j)Psi - i G_j d_j Psi - i G_j D_j Psi
	//
	// Each -i G ... piece is just EWGaugeAct applied to a different argument,
	// so the whole covariant Laplacian composes out of the one operation.
	// Spatial gradients of all twelve W components. These serve double duty:
	// their traces give the divergences the Higgs covariant Laplacian needs,
	// and the full tensor is what the Yang-Mills self-coupling runs on.
	g10 := Gradient10(x, y, z, int32(EWW10s), prv)
	g1x := Gradient10(x, y, z, int32(EWW1Xs), prv)
	g1y := Gradient10(x, y, z, int32(EWW1Ys), prv)
	g1z := Gradient10(x, y, z, int32(EWW1Zs), prv)
	g20 := Gradient10(x, y, z, int32(EWW20s), prv)
	g2x := Gradient10(x, y, z, int32(EWW2Xs), prv)
	g2y := Gradient10(x, y, z, int32(EWW2Ys), prv)
	g2z := Gradient10(x, y, z, int32(EWW2Zs), prv)
	g30 := Gradient10(x, y, z, int32(EWW30s), prv)
	g3x := Gradient10(x, y, z, int32(EWW3Xs), prv)
	g3y := Gradient10(x, y, z, int32(EWW3Ys), prv)
	g3z := Gradient10(x, y, z, int32(EWW3Zs), prv)

	dvW1 := g1x.X + g1y.Y + g1z.Z
	dvW2 := g2x.X + g2y.Y + g2z.Z
	dvW3 := g3x.X + g3y.Y + g3z.Z
	dvB := EWDiv(x, y, z, int32(EWBXs), prv)

	lap := math32.Vec4(Laplacian19(x, y, z, int32(EWHsCa), prv, psi.X),
		Laplacian19(x, y, z, int32(EWHsCb), prv, psi.Y),
		Laplacian19(x, y, z, int32(EWHs0a), prv, psi.Z),
		Laplacian19(x, y, z, int32(EWHs0b), prv, psi.W))

	cov := lap.Add(EWGaugeAct(dvW1, dvW2, dvW3, dvB, psi))
	cov = cov.Add(EWGaugeAct(w1x, w2x, w3x, bx, dxp.Add(dX)))
	cov = cov.Add(EWGaugeAct(w1y, w2y, w3y, by, dyp.Add(dY)))
	cov = cov.Add(EWGaugeAct(w1z, w2z, w3z, bz, dzp.Add(dZ)))

	// ---- time-component gauge terms ---------------------------------------
	// D_0 D_0 Psi expands exactly as the spatial case does:
	//
	//	D_0D_0 Psi = (1/c^2) d_t^2 Psi + (1/c)(d_t G_0) Psi
	//	             + (1/c) G_0 d_t Psi + G_0 D_0 Psi
	//
	// and the equation of motion is D_0D_0 = vfac + D_jD_j, so solving it for
	// the acceleration SUBTRACTS the last three. Without these the Higgs
	// sources W_0 and B_0 through j_0 but never feels them back, which breaks
	// gauge invariance: a constant A_0 is pure gauge and must produce a phase
	// rotation at constant |Phi|, not a change in the magnitude.
	w1xv := State.Value(int(z), int(y), int(x), int(EWW1Xv), int(prv))
	w1yv := State.Value(int(z), int(y), int(x), int(EWW1Yv), int(prv))
	w1zv := State.Value(int(z), int(y), int(x), int(EWW1Zv), int(prv))
	w2xv := State.Value(int(z), int(y), int(x), int(EWW2Xv), int(prv))
	w2yv := State.Value(int(z), int(y), int(x), int(EWW2Yv), int(prv))
	w2zv := State.Value(int(z), int(y), int(x), int(EWW2Zv), int(prv))
	w3xv := State.Value(int(z), int(y), int(x), int(EWW3Xv), int(prv))
	w3yv := State.Value(int(z), int(y), int(x), int(EWW3Yv), int(prv))
	w3zv := State.Value(int(z), int(y), int(x), int(EWW3Zv), int(prv))
	w10v := State.Value(int(z), int(y), int(x), int(EWW10v), int(prv))
	w20v := State.Value(int(z), int(y), int(x), int(EWW20v), int(prv))
	w30v := State.Value(int(z), int(y), int(x), int(EWW30v), int(prv))
	b0v := State.Value(int(z), int(y), int(x), int(EWB0v), int(prv))

	// Of the three, only the two built on dtp depend on the Higgs VELOCITY.
	// Together they are -2 G_0 (dPsi/dt)/c, i.e. exactly the connection acting
	// on the velocity -- a rotation. With Boris on they are left out here and
	// applied exactly below; otherwise they go in explicitly as before.
	q0 := EWGaugeAct(oc*w10v, oc*w20v, oc*w30v, oc*b0v, psi)
	qa := EWGaugeAct(w10, w20, w30, b0, a0)
	cov = cov.Sub(q0).Sub(qa)
	if !boris {
		qv := EWGaugeAct(w10, w20, w30, b0, dtp)
		cov = cov.Sub(qv).Sub(qv)
	}

	// ---- the potential ----------------------------------------------------
	// V = -(1/2) mu^2 mag + (1/4) lambda mag^2
	// force_i = -dV/dphi_i = (mu^2 - lambda*mag) * phi_i
	// The SAME radial factor multiplies EACH component, so the force points
	// along the field vector and depends only on |Phi|. That leaves the phase
	// directions exactly flat -- the Goldstone modes. At the vacuum
	// mag = mu^2/lambda, vfac = 0, and the state is exactly stationary.
	mag := psi.X*psi.X + psi.Y*psi.Y + psi.Z*psi.Z + psi.W*psi.W
	vfac := musq - lambda*mag

	hf := math32.Vec4(csq*(cov.X+vfac*psi.X), csq*(cov.Y+vfac*psi.Y),
		csq*(cov.Z+vfac*psi.Z), csq*(cov.W+vfac*psi.W))

	// ---- the Yukawa term seen from the Higgs side -------------------------
	//
	// Params.SelfField again: the same -y (Lbar Phi e_R + h.c.) that gives the
	// electron its mass is a force on the Higgs, and this is the other end of
	// it. Varying that term by Phi^dag rather than by the fermion leaves the
	// fermion bilinear behind:
	//
	//	source(phi^0) = -sqrt(2) y (e_R^dag e_L)
	//	source(phi^+) = -sqrt(2) y (e_R^dag nu_L)
	//
	// and it enters the acceleration where the Laplacian does, since both come
	// from the same box operator. The sqrt(2) is the stored doublet being
	// sqrt(2) Phi, as EWCurrent notes; there is no further factor, because the
	// coupling is the one y and nothing else.
	//
	// Without this the condensate is an infinite reservoir: it hands out mass
	// and never notices. With it, a dense enough lump of electron pushes |Phi|
	// down where it sits, which lowers its own mass there -- the field and the
	// particle finally arguing with each other.
	if Params[0].SelfField.IsTrue() {
		nu1 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWNu1a), int(prv)), State.Value(int(z), int(y), int(x), int(EWNu1b), int(prv)))
		nu2 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWNu2a), int(prv)), State.Value(int(z), int(y), int(x), int(EWNu2b), int(prv)))
		el1 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWEL1a), int(prv)), State.Value(int(z), int(y), int(x), int(EWEL1b), int(prv)))
		el2 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWEL2a), int(prv)), State.Value(int(z), int(y), int(x), int(EWEL2b), int(prv)))
		er1 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWER1a), int(prv)), State.Value(int(z), int(y), int(x), int(EWER1b), int(prv)))
		er2 := math32.Vec2(State.Value(int(z), int(y), int(x), int(EWER2a), int(prv)), State.Value(int(z), int(y), int(x), int(EWER2b), int(prv)))
		re := EWSpinBilinear(0, er1, er2, el1, el2) // e_R^dag e_L
		rn := EWSpinBilinear(0, er1, er2, nu1, nu2) // e_R^dag nu_L
		yh := -csq * Sqrt2 * Params[0].YukawaE
		hf.X += yh * rn.X
		hf.Y += yh * rn.Y
		hf.Z += yh * re.X
		hf.W += yh * re.Y
	}

	// ---- currents, one per spacetime index --------------------------------
	j0 := EWCurrent(psi, d0)
	jx := EWCurrent(psi, dX)
	jy := EWCurrent(psi, dY)
	jz := EWCurrent(psi, dZ)

	// Params.SelfField: the leptons source the gauge fields as well as feeling
	// them. Read at prv, like everything else here, so EWFermionKernel can run
	// either side of this one. Off, they are test fields -- they move in the
	// electroweak background and leave no trace in it.
	if Params[0].SelfField.IsTrue() {
		j0 = j0.Add(EWLeptonCurrent(x, y, z, prv, 0))
		jx = jx.Add(EWLeptonCurrent(x, y, z, prv, 1))
		jy = jy.Add(EWLeptonCurrent(x, y, z, prv, 2))
		jz = jz.Add(EWLeptonCurrent(x, y, z, prv, 3))
	}

	// ---- Yang-Mills self-coupling -----------------------------------------
	// Adjoint 3-vectors: for each spacetime index mu, the SU(2) triplet
	// (W^1_mu, W^2_mu, W^3_mu). In this form every eps^{abc} becomes a cross
	// product and the whole self-coupling is a handful of them.
	var ym0, ymx, ymy, ymz math32.Vector3
	if Params[0].YangMills.IsTrue() {
		gw := Params[0].GW
		w0 := math32.Vec3(w10, w20, w30)
		// wb is w0 for the explicit path; with Boris it is zeroed so the
		// mu = 0 transport term (the velocity-dependent one) is handled by the
		// exact rotation instead of being integrated explicitly.
		wb := w0
		if boris {
			wb = math32.Vec3(0, 0, 0)
		}
		wx := math32.Vec3(w1x, w2x, w3x)
		wy := math32.Vec3(w1y, w2y, w3y)
		wz := math32.Vec3(w1z, w2z, w3z)

		// d_mu W^nu, indexed [derivative direction][component]. The time
		// derivatives are the stored velocities: per step, so divide by c to
		// land in the same 1/cube units as the spatial gradients.
		t0 := math32.Vec3(w10v, w20v, w30v).MulScalar(oc)
		tx := math32.Vec3(w1xv, w2xv, w3xv).MulScalar(oc)
		ty := math32.Vec3(w1yv, w2yv, w3yv).MulScalar(oc)
		tz := math32.Vec3(w1zv, w2zv, w3zv).MulScalar(oc)

		x0 := math32.Vec3(g10.X, g20.X, g30.X)
		y0 := math32.Vec3(g10.Y, g20.Y, g30.Y)
		z0 := math32.Vec3(g10.Z, g20.Z, g30.Z)
		xx := math32.Vec3(g1x.X, g2x.X, g3x.X)
		yx := math32.Vec3(g1x.Y, g2x.Y, g3x.Y)
		zx := math32.Vec3(g1x.Z, g2x.Z, g3x.Z)
		xy := math32.Vec3(g1y.X, g2y.X, g3y.X)
		yy := math32.Vec3(g1y.Y, g2y.Y, g3y.Y)
		zy := math32.Vec3(g1y.Z, g2y.Z, g3y.Z)
		xz := math32.Vec3(g1z.X, g2z.X, g3z.X)
		yz := math32.Vec3(g1z.Y, g2z.Y, g3z.Y)
		zz := math32.Vec3(g1z.Z, g2z.Z, g3z.Z)

		// divergence d.W^a = d_0 W^{a0} + d_j W^{aj}, as an adjoint vector
		dv := t0.Add(xx).Add(yy).Add(zz)

		// [transport] -2g sum_mu (W^mu x d_mu W^nu)  (upper-lower, no signs)
		// [transpose] +g sum_mu (W_mu x d^nu W^mu)   (metric signs, and
		//
		//	d^nu = +d_0 for nu=0 but -d_j for nu=j)
		//
		// [quartic]   -g^2 sum_mu (W_mu x (W^mu x W^nu))
		// [divergence] -g (dv x W^nu)
		ym0 = EWCrossUp(wb, wx, wy, wz, t0, x0, y0, z0).MulScalar(2 * gw)
		ym0 = ym0.Sub(EWCrossLor(w0, wx, wy, wz, t0, tx, ty, tz).MulScalar(gw))
		ym0 = ym0.Sub(EWCrossLor(w0, wx, wy, wz,
			slmath.Cross3(w0, w0), slmath.Cross3(wx, w0),
			slmath.Cross3(wy, w0), slmath.Cross3(wz, w0)).MulScalar(gw * gw))
		ym0 = ym0.Add(slmath.Cross3(dv, w0).MulScalar(gw))

		ymx = EWCrossUp(wb, wx, wy, wz, tx, xx, yx, zx).MulScalar(2 * gw)
		ymx = ymx.Add(EWCrossLor(w0, wx, wy, wz, x0, xx, xy, xz).MulScalar(gw))
		ymx = ymx.Sub(EWCrossLor(w0, wx, wy, wz,
			slmath.Cross3(w0, wx), slmath.Cross3(wx, wx),
			slmath.Cross3(wy, wx), slmath.Cross3(wz, wx)).MulScalar(gw * gw))
		ymx = ymx.Add(slmath.Cross3(dv, wx).MulScalar(gw))

		ymy = EWCrossUp(wb, wx, wy, wz, ty, xy, yy, zy).MulScalar(2 * gw)
		ymy = ymy.Add(EWCrossLor(w0, wx, wy, wz, y0, yx, yy, yz).MulScalar(gw))
		ymy = ymy.Sub(EWCrossLor(w0, wx, wy, wz,
			slmath.Cross3(w0, wy), slmath.Cross3(wx, wy),
			slmath.Cross3(wy, wy), slmath.Cross3(wz, wy)).MulScalar(gw * gw))
		ymy = ymy.Add(slmath.Cross3(dv, wy).MulScalar(gw))

		ymz = EWCrossUp(wb, wx, wy, wz, tz, xz, yz, zz).MulScalar(2 * gw)
		ymz = ymz.Add(EWCrossLor(w0, wx, wy, wz, z0, zx, zy, zz).MulScalar(gw))
		ymz = ymz.Sub(EWCrossLor(w0, wx, wy, wz,
			slmath.Cross3(w0, wz), slmath.Cross3(wx, wz),
			slmath.Cross3(wy, wz), slmath.Cross3(wz, wz)).MulScalar(gw * gw))
		ymz = ymz.Add(slmath.Cross3(dv, wz).MulScalar(gw))
	}

	// ---- gauge field updates: box W = j, box B = j^Y ----------------------
	// Omega for the Boris rotation of the W velocities: the transport term is
	// dv/dt = v x Omega with Omega = -2 g c W_0.
	omW := math32.Vec3(w10, w20, w30).MulScalar(-2 * Params[0].GW * Params[0].C)
	nw := Params[0].A0NoWave.IsTrue()
	EWWStep(x, y, z, cur, prv, 0, csq, omW, math32.Vec3(j0.X+ym0.X, j0.Y+ym0.Y, j0.Z+ym0.Z), boris, nw)
	EWWStep(x, y, z, cur, prv, 1, csq, omW, math32.Vec3(jx.X+ymx.X, jx.Y+ymx.Y, jx.Z+ymx.Z), boris, nw)
	EWWStep(x, y, z, cur, prv, 2, csq, omW, math32.Vec3(jy.X+ymy.X, jy.Y+ymy.Y, jy.Z+ymy.Z), boris, nw)
	EWWStep(x, y, z, cur, prv, 3, csq, omW, math32.Vec3(jz.X+ymz.X, jz.Y+ymz.Y, jz.Z+ymz.Z), boris, nw)
	EWGaugeStep(x, y, z, cur, prv, int32(EWB0s), csq, j0.W, jx.W, jy.W, jz.W, nw)

	// ---- Higgs update ------------------------------------------------------
	var hvN math32.Vector4
	if boris {
		hh := hf.MulScalar(0.5)
		hvN = EWBorisPhase(w10, w20, w30, b0, 2*Params[0].C, psv.Add(hh)).Add(hh)
	} else {
		hvN = psv.Add(hf)
	}
	hvCaN := hvN.X
	hvCbN := hvN.Y
	hv0aN := hvN.Z
	hv0bN := hvN.W

	State.Set(psi.X+hvCaN, int(z), int(y), int(x), int(EWHsCa), int(cur))
	State.Set(psi.Y+hvCbN, int(z), int(y), int(x), int(EWHsCb), int(cur))
	State.Set(psi.Z+hv0aN, int(z), int(y), int(x), int(EWHs0a), int(cur))
	State.Set(psi.W+hv0bN, int(z), int(y), int(x), int(EWHs0b), int(cur))

	State.Set(hvCaN, int(z), int(y), int(x), int(EWHvCa), int(cur))
	State.Set(hvCbN, int(z), int(y), int(x), int(EWHvCb), int(cur))
	State.Set(hv0aN, int(z), int(y), int(x), int(EWHv0a), int(cur))
	State.Set(hv0bN, int(z), int(y), int(x), int(EWHv0b), int(cur))

	// ---- mass-eigenstate views ---------------------------------------------
	// Rotate the freshly-updated (W^3, B) pair through the weak mixing angle.
	// The photon goes into the ordinary Maxwell variables: it IS the
	// electromagnetic field, so A0s..AZs is where it belongs. Nothing here is
	// evolved -- these are recomputed from the gauge basis every step, which is
	// why StepRun must NOT also run MaxwellKernel in Electroweak mode.
	sw := Params[0].SinThetaW
	cw := Params[0].CosThetaW
	for k := range 4 {
		ki := int32(k)
		w3s := State.Value(int(z), int(y), int(x), int(int32(EWW30s)+ki), int(cur))
		w3v := State.Value(int(z), int(y), int(x), int(int32(EWW30v)+ki), int(cur))
		bs := State.Value(int(z), int(y), int(x), int(int32(EWB0s)+ki), int(cur))
		bv := State.Value(int(z), int(y), int(x), int(int32(EWB0v)+ki), int(cur))
		State.Set(sw*w3s+cw*bs, int(z), int(y), int(x), int(int32(A0s)+ki), int(cur))
		State.Set(sw*w3v+cw*bv, int(z), int(y), int(x), int(int32(A0v)+ki), int(cur))
		State.Set(cw*w3s-sw*bs, int(z), int(y), int(x), int(int32(EWZ0)+ki), int(cur))

		w1s := State.Value(int(z), int(y), int(x), int(int32(EWW10s)+ki), int(cur))
		w2s := State.Value(int(z), int(y), int(x), int(int32(EWW20s)+ki), int(cur))
		State.Set(w1s*InvSqrt2, int(z), int(y), int(x), int(int32(EWWPr0)+ki), int(cur))
		State.Set(-w2s*InvSqrt2, int(z), int(y), int(x), int(int32(EWWPi0)+ki), int(cur))
	}
	wm := float32(0)
	for k := range 4 {
		ki := int32(k)
		w1s := State.Value(int(z), int(y), int(x), int(int32(EWW10s)+ki), int(cur))
		w2s := State.Value(int(z), int(y), int(x), int(int32(EWW20s)+ki), int(cur))
		wm += 0.5 * (w1s*w1s + w2s*w2s)
	}
	State.Set(wm, int(z), int(y), int(x), int(EWWMag), int(cur))

	State.Set(mag, int(z), int(y), int(x), int(EWHmag), int(cur))
	State.Set(-0.5*musq*mag+0.25*lambda*mag*mag, int(z), int(y), int(x), int(EWHV), int(cur))
}

// EWWStep advances the twelve SU(2) potentials. src carries the
// velocity-INDEPENDENT source (current + the explicit Yang-Mills terms) for one
// spacetime index, as an adjoint 3-vector; the Laplacian is added here.
//
// With Boris on, the velocity-dependent transport term -- which is exactly
// dv/dt = v x Omega with Omega = -2 g c W_0 -- is applied as a true rotation
// between two half kicks, instead of being lumped into the explicit force.
func EWWStep(x, y, z, cur, prv, nu int32, csq float32, om, src math32.Vector3, boris, noWave bool) {
	vs := int32(EWW10s) + nu
	vv := int32(EWW10v) + nu
	p1 := State.Value(int(z), int(y), int(x), int(vs), int(prv))
	p2 := State.Value(int(z), int(y), int(x), int(vs+8), int(prv))
	p3 := State.Value(int(z), int(y), int(x), int(vs+16), int(prv))
	l1 := Laplacian19(x, y, z, vs, prv, p1)
	l2 := Laplacian19(x, y, z, vs+8, prv, p2)
	l3 := Laplacian19(x, y, z, vs+16, prv, p3)
	f := math32.Vec3(csq*(l1+src.X), csq*(l2+src.Y), csq*(l3+src.Z))
	q1 := State.Value(int(z), int(y), int(x), int(vv), int(prv))
	q2 := State.Value(int(z), int(y), int(x), int(vv+8), int(prv))
	q3 := State.Value(int(z), int(y), int(x), int(vv+16), int(prv))
	v := math32.Vec3(q1, q2, q3)
	var vn math32.Vector3
	if noWave && nu == 0 {
		// Params.A0NoWave: drive the SCALAR potential straight from the force
		// rather than accumulating it into a velocity. The nu = 0 sector is the
		// gauge direction, whose linearised system has a degenerate eigenvalue
		// and so carries a secular (A + B t) branch -- it drifts without bound
		// even though the physics does not. Dropping its wave dynamics is the
		// same Sommerfeld-style fix MaxwellKernel already uses for A0.
		vn = f
	} else if boris {
		h := f.MulScalar(0.5)
		vn = EWBorisRot3(v.Add(h), om).Add(h)
	} else {
		vn = v.Add(f)
	}
	State.Set(vn.X, int(z), int(y), int(x), int(vv), int(cur))
	State.Set(vn.Y, int(z), int(y), int(x), int(vv+8), int(cur))
	State.Set(vn.Z, int(z), int(y), int(x), int(vv+16), int(cur))
	State.Set(p1+vn.X, int(z), int(y), int(x), int(vs), int(cur))
	State.Set(p2+vn.Y, int(z), int(y), int(x), int(vs+8), int(cur))
	State.Set(p3+vn.Z, int(z), int(y), int(x), int(vs+16), int(cur))
}

// EWGaugeStep advances one four-potential (the 0,X,Y,Z state variables
// starting at v0, with their four velocities at v0+4) by one leapfrog step of
//
//	d2 A_mu / dt2 = c^2 [ lap(A_mu) + j_mu ]
//
// which is box A_mu = j_mu in Lorenz gauge -- the same equation MaxwellKernel
// solves for the photon, with the electroweak current in place of the
// electromagnetic one. No mass term appears here or anywhere else.
func EWGaugeStep(x, y, z, cur, prv, v0 int32, csq, j0, jx, jy, jz float32, noWave bool) {
	for ki := range 4 {
		k := int32(ki)
		vs := v0 + k
		vv := v0 + 4 + k
		var jc float32
		switch ki {
		case 0:
			jc = j0
		case 1:
			jc = jx
		case 2:
			jc = jy
		default:
			jc = jz
		}
		ps := State.Value(int(z), int(y), int(x), int(vs), int(prv))
		vp := State.Value(int(z), int(y), int(x), int(vv), int(prv))
		f := csq * (Laplacian19(x, y, z, vs, prv, ps) + jc)
		vc := vp + f
		if noWave && ki == 0 {
			vc = f // see EWWStep: the scalar potential is the gauge direction
		}
		State.Set(vc, int(z), int(y), int(x), int(vv), int(cur))
		State.Set(ps+vc, int(z), int(y), int(x), int(vs), int(cur))
	}
}

// ElectroweakDampKernel damps the gauge fields at the boundary and leaves the
// Higgs alone, which is the one thing this equation needs that none of the
// others do.
//
// The gauge fields get Sommerfeld damping like Maxwell's, force setting the
// velocity instead of adding to it. The Higgs cannot: it has a vacuum that is
// not zero, and the reasons are set out where it is handled below.
// EWFermionKernel evolves one generation of leptons in the electroweak
// background: the left-handed doublet (nu_L, e_L) and the right-handed
// singlet e_R, each a Weyl 2-spinor.
//
//	d_t nu_L = +c sigma.D nu_L - i y phi^+  e_R
//	d_t e_L  = +c sigma.D e_L  - i y phi^0  e_R
//	d_t e_R  = -c sigma.D e_R  - i y (phi^+* nu_L + phi^0* e_L)
//
// It is [WeylKernel] with two things taken out of the parameter list and put
// into the fields. The mass is not a number: it is the Yukawa coupling times
// the HIGGS, so it varies in space, it responds to the condensate, and it
// vanishes when the symmetry is restored. And the charge is not a number
// either: it is the gauge structure, through which component of the doublet a
// field sits in.
//
// In the broken vacuum phi^+ = 0 and phi^0 = v, so the only surviving term is
// -i (y v / sqrt(2)) between e_L and e_R, and this reduces EXACTLY to
// WeylKernel at Omega0 = m_e. The neutrino keeps nothing at all, because the
// upper component's partner would be a nu_R and there isn't one. Excite the
// charged Higgs and phi^+ coupling switches on, which is the same term doing
// what it does in a W decay.
//
// Runs after [ElectroweakKernel] in the same step and reads only prv, which
// that kernel does not write, so the order between them does not matter.
func EWFermionKernel(i uint32) { //gosl:kernel
	ctx := GetCtx(0)
	var x, y, z int32
	ok := ctx.StateCoords(i, &x, &y, &z)
	if !ok {
		return
	}
	cur := ctx.CurState
	prv := ctx.PrevState()

	// the three-level leapfrog: cur still holds u(t-1) until we write it
	on1a := State.Value(int(z), int(y), int(x), int(EWNu1a), int(cur))
	on1b := State.Value(int(z), int(y), int(x), int(EWNu1b), int(cur))
	on2a := State.Value(int(z), int(y), int(x), int(EWNu2a), int(cur))
	on2b := State.Value(int(z), int(y), int(x), int(EWNu2b), int(cur))
	ol1a := State.Value(int(z), int(y), int(x), int(EWEL1a), int(cur))
	ol1b := State.Value(int(z), int(y), int(x), int(EWEL1b), int(cur))
	ol2a := State.Value(int(z), int(y), int(x), int(EWEL2a), int(cur))
	ol2b := State.Value(int(z), int(y), int(x), int(EWEL2b), int(cur))
	or1a := State.Value(int(z), int(y), int(x), int(EWER1a), int(cur))
	or1b := State.Value(int(z), int(y), int(x), int(EWER1b), int(cur))
	or2a := State.Value(int(z), int(y), int(x), int(EWER2a), int(cur))
	or2b := State.Value(int(z), int(y), int(x), int(EWER2b), int(cur))

	// u(t), where the right-hand side is evaluated
	nn1a := State.Value(int(z), int(y), int(x), int(EWNu1a), int(prv))
	nn1b := State.Value(int(z), int(y), int(x), int(EWNu1b), int(prv))
	nn2a := State.Value(int(z), int(y), int(x), int(EWNu2a), int(prv))
	nn2b := State.Value(int(z), int(y), int(x), int(EWNu2b), int(prv))
	nl1a := State.Value(int(z), int(y), int(x), int(EWEL1a), int(prv))
	nl1b := State.Value(int(z), int(y), int(x), int(EWEL1b), int(prv))
	nl2a := State.Value(int(z), int(y), int(x), int(EWEL2a), int(prv))
	nl2b := State.Value(int(z), int(y), int(x), int(EWEL2b), int(prv))
	nr1a := State.Value(int(z), int(y), int(x), int(EWER1a), int(prv))
	nr1b := State.Value(int(z), int(y), int(x), int(EWER1b), int(prv))
	nr2a := State.Value(int(z), int(y), int(x), int(EWER2a), int(prv))
	nr2b := State.Value(int(z), int(y), int(x), int(EWER2b), int(prv))

	gn1a := Gradient10(x, y, z, int32(EWNu1a), prv)
	gn1b := Gradient10(x, y, z, int32(EWNu1b), prv)
	gn2a := Gradient10(x, y, z, int32(EWNu2a), prv)
	gn2b := Gradient10(x, y, z, int32(EWNu2b), prv)
	gl1a := Gradient10(x, y, z, int32(EWEL1a), prv)
	gl1b := Gradient10(x, y, z, int32(EWEL1b), prv)
	gl2a := Gradient10(x, y, z, int32(EWEL2a), prv)
	gl2b := Gradient10(x, y, z, int32(EWEL2b), prv)
	gr1a := Gradient10(x, y, z, int32(EWER1a), prv)
	gr1b := Gradient10(x, y, z, int32(EWER1b), prv)
	gr2a := Gradient10(x, y, z, int32(EWER2a), prv)
	gr2b := Gradient10(x, y, z, int32(EWER2b), prv)

	// sigma.grad on a 2-spinor, component by component, exactly as WeylKernel
	sn1a := gn1a.Z + gn2a.X + gn2b.Y
	sn1b := gn1b.Z + gn2b.X - gn2a.Y
	sn2a := gn1a.X - gn1b.Y - gn2a.Z
	sn2b := gn1b.X + gn1a.Y - gn2b.Z
	sl1a := gl1a.Z + gl2a.X + gl2b.Y
	sl1b := gl1b.Z + gl2b.X - gl2a.Y
	sl2a := gl1a.X - gl1b.Y - gl2a.Z
	sl2b := gl1b.X + gl1a.Y - gl2b.Z
	sr1a := gr1a.Z + gr2a.X + gr2b.Y
	sr1b := gr1b.Z + gr2b.X - gr2a.Y
	sr2a := gr1a.X - gr1b.Y - gr2a.Z
	sr2b := gr1b.X + gr1a.Y - gr2b.Z

	cc := Params[0].C
	// left streams one way, right the other: that is all chirality is
	dn1a := cc * sn1a
	dn1b := cc * sn1b
	dn2a := cc * sn2a
	dn2b := cc * sn2b
	dl1a := cc * sl1a
	dl1b := cc * sl1b
	dl2a := cc * sl2a
	dl2b := cc * sl2b
	dr1a := -cc * sr1a
	dr1b := -cc * sr1b
	dr2a := -cc * sr2a
	dr2b := -cc * sr2b

	// ---- the Yukawa term, which is the mass ------------------------------
	//
	// The stored doublet is sqrt(2) Phi, as EWCurrent notes, so the coupling
	// carried around here is y / sqrt(2) and m_e = y v / sqrt(2) comes out of
	// the vacuum value directly.
	//
	// -i M psi with COMPLEX M takes (a, b) to (Ma b + Mb a, Mb b - Ma a), and
	// the conjugate M* flips the sign of Mb. That pairing is what conserves
	// |nu|^2 + |e_L|^2 + |e_R|^2: the term moves amplitude between them and
	// creates none.
	// the c is the same one c sigma.grad carries: the stored Higgs is a 1/cube
	// quantity, so y phi is an inverse Compton length and c y phi is the rate
	// per step that L and R actually trade at. Params.MassE is the former.
	ye := Params[0].YukawaE * InvSqrt2 * cc
	hca := ye * State.Value(int(z), int(y), int(x), int(EWHsCa), int(prv))
	hcb := ye * State.Value(int(z), int(y), int(x), int(EWHsCb), int(prv))
	h0a := ye * State.Value(int(z), int(y), int(x), int(EWHs0a), int(prv))
	h0b := ye * State.Value(int(z), int(y), int(x), int(EWHs0b), int(prv))

	dn1a += hca*nr1b + hcb*nr1a
	dn1b += hcb*nr1b - hca*nr1a
	dn2a += hca*nr2b + hcb*nr2a
	dn2b += hcb*nr2b - hca*nr2a
	dl1a += h0a*nr1b + h0b*nr1a
	dl1b += h0b*nr1b - h0a*nr1a
	dl2a += h0a*nr2b + h0b*nr2a
	dl2b += h0b*nr2b - h0a*nr2a
	dr1a += (hca*nn1b - hcb*nn1a) + (h0a*nl1b - h0b*nl1a)
	dr1b += (-hcb*nn1b - hca*nn1a) + (-h0b*nl1b - h0a*nl1a)
	dr2a += (hca*nn2b - hcb*nn2a) + (h0a*nl2b - h0b*nl2a)
	dr2b += (-hcb*nn2b - hca*nn2a) + (-h0b*nl2b - h0a*nl2a)

	// ---- gauge coupling -------------------------------------------------
	//
	// The same minimal coupling WeylKernel has, with the charge promoted from
	// a number to a matrix: G_mu = g W^a_mu T^a + g' Y B_mu, acting on the
	// WEAK index while sigma acts on the spin index. The two commute, so the
	// potential is applied first and contracted with sigma afterwards, in the
	// identical component pattern the gradient uses.
	//
	//	d_t psi_L += i c (G_0 + sigma.G) psi_L
	//	d_t psi_R += i c (G_0 - sigma.G) psi_R
	//
	// The c is not decoration. G here is the same object the Higgs kernel puts
	// in its covariant derivative, so it is a 1/cube quantity like a gradient,
	// and d_t is per step: the free term c sigma.grad carries exactly the same
	// factor. Leaving it out makes the coupling 1/c too strong.
	//
	// The left doublet sees all of it. The right electron is an SU(2) singlet,
	// so its G is g' Y B alone -- no W at all, which is what
	// "the weak force only touches left-handed fields"
	// means in the equation rather than in words.
	if Params[0].EM.IsTrue() {
		w10 := State.Value(int(z), int(y), int(x), int(EWW10s), int(prv))
		w1x := State.Value(int(z), int(y), int(x), int(EWW1Xs), int(prv))
		w1y := State.Value(int(z), int(y), int(x), int(EWW1Ys), int(prv))
		w1z := State.Value(int(z), int(y), int(x), int(EWW1Zs), int(prv))
		w20 := State.Value(int(z), int(y), int(x), int(EWW20s), int(prv))
		w2x := State.Value(int(z), int(y), int(x), int(EWW2Xs), int(prv))
		w2y := State.Value(int(z), int(y), int(x), int(EWW2Ys), int(prv))
		w2z := State.Value(int(z), int(y), int(x), int(EWW2Zs), int(prv))
		w30 := State.Value(int(z), int(y), int(x), int(EWW30s), int(prv))
		w3x := State.Value(int(z), int(y), int(x), int(EWW3Xs), int(prv))
		w3y := State.Value(int(z), int(y), int(x), int(EWW3Ys), int(prv))
		w3z := State.Value(int(z), int(y), int(x), int(EWW3Zs), int(prv))
		b0 := State.Value(int(z), int(y), int(x), int(EWB0s), int(prv))
		bx := State.Value(int(z), int(y), int(x), int(EWBXs), int(prv))
		by := State.Value(int(z), int(y), int(x), int(EWBYs), int(prv))
		bz := State.Value(int(z), int(y), int(x), int(EWBZs), int(prv))

		// the doublet at each spin component: (nu real, nu imag, e real, e imag)
		p1 := math32.Vec4(nn1a, nn1b, nl1a, nl1b)
		p2 := math32.Vec4(nn2a, nn2b, nl2a, nl2b)
		q01 := EWGaugeMul(w10, w20, w30, b0, YLep, p1)
		qx1 := EWGaugeMul(w1x, w2x, w3x, bx, YLep, p1)
		qy1 := EWGaugeMul(w1y, w2y, w3y, by, YLep, p1)
		qz1 := EWGaugeMul(w1z, w2z, w3z, bz, YLep, p1)
		q02 := EWGaugeMul(w10, w20, w30, b0, YLep, p2)
		qx2 := EWGaugeMul(w1x, w2x, w3x, bx, YLep, p2)
		qy2 := EWGaugeMul(w1y, w2y, w3y, by, YLep, p2)
		qz2 := EWGaugeMul(w1z, w2z, w3z, bz, YLep, p2)

		// (G_0 + sigma.G) Psi, in the sigma pattern of sn/sl above
		u1a := q01.X + qz1.X + qx2.X + qy2.Y
		u1b := q01.Y + qz1.Y + qx2.Y - qy2.X
		u2a := q02.X + qx1.X - qy1.Y - qz2.X
		u2b := q02.Y + qx1.Y + qy1.X - qz2.Y
		v1a := q01.Z + qz1.Z + qx2.Z + qy2.W
		v1b := q01.W + qz1.W + qx2.W - qy2.Z
		v2a := q02.Z + qx1.Z - qy1.W - qz2.Z
		v2b := q02.W + qx1.W + qy1.Z - qz2.W

		// multiplying by i takes (a, b) to (-b, a)
		dn1a -= cc * u1b
		dn1b += cc * u1a
		dn2a -= cc * u2b
		dn2b += cc * u2a
		dl1a -= cc * v1b
		dl1b += cc * v1a
		dl2a -= cc * v2b
		dl2b += cc * v2a

		// the singlet: hypercharge only, and the other chirality sign
		gb := Params[0].GpW * YER
		rb0 := gb * b0
		rbx := gb * bx
		rby := gb * by
		rbz := gb * bz
		qr1a := rb0*nr1a - (rbz*nr1a + rbx*nr2a + rby*nr2b)
		qr1b := rb0*nr1b - (rbz*nr1b + rbx*nr2b - rby*nr2a)
		qr2a := rb0*nr2a - (rbx*nr1a - rby*nr1b - rbz*nr2a)
		qr2b := rb0*nr2b - (rbx*nr1b + rby*nr1a - rbz*nr2b)
		dr1a -= cc * qr1b
		dr1b += cc * qr1a
		dr2a -= cc * qr2b
		dr2b += cc * qr2a
	}

	n1a := on1a + 2*dn1a
	n1b := on1b + 2*dn1b
	n2a := on2a + 2*dn2a
	n2b := on2b + 2*dn2b
	l1a := ol1a + 2*dl1a
	l1b := ol1b + 2*dl1b
	l2a := ol2a + 2*dl2a
	l2b := ol2b + 2*dl2b
	r1a := or1a + 2*dr1a
	r1b := or1b + 2*dr1b
	r2a := or2a + 2*dr2a
	r2b := or2b + 2*dr2b

	if Params[0].Edges == EdgesDamp { // the absorbing layer: see EdgeDampFactor
		df := EdgeDampFactor(x, y, z, ctx.Size.V())
		n1a *= df
		n1b *= df
		n2a *= df
		n2b *= df
		l1a *= df
		l1b *= df
		l2a *= df
		l2b *= df
		r1a *= df
		r1b *= df
		r2a *= df
		r2b *= df
	}

	State.Set(n1a, int(z), int(y), int(x), int(EWNu1a), int(cur))
	State.Set(n1b, int(z), int(y), int(x), int(EWNu1b), int(cur))
	State.Set(n2a, int(z), int(y), int(x), int(EWNu2a), int(cur))
	State.Set(n2b, int(z), int(y), int(x), int(EWNu2b), int(cur))
	State.Set(l1a, int(z), int(y), int(x), int(EWEL1a), int(cur))
	State.Set(l1b, int(z), int(y), int(x), int(EWEL1b), int(cur))
	State.Set(l2a, int(z), int(y), int(x), int(EWEL2a), int(cur))
	State.Set(l2b, int(z), int(y), int(x), int(EWEL2b), int(cur))
	State.Set(r1a, int(z), int(y), int(x), int(EWER1a), int(cur))
	State.Set(r1b, int(z), int(y), int(x), int(EWER1b), int(cur))
	State.Set(r2a, int(z), int(y), int(x), int(EWER2a), int(cur))
	State.Set(r2b, int(z), int(y), int(x), int(EWER2b), int(cur))

	// the STAGGERED magnitudes, as WeylKernel uses: a three-level leapfrog
	// conserves the product of adjacent levels, not the square of one
	nm := nn1a*n1a + nn1b*n1b + nn2a*n2a + nn2b*n2b
	lm := nl1a*l1a + nl1b*l1b + nl2a*l2a + nl2b*l2b
	rm := nr1a*r1a + nr1b*r1b + nr2a*r2a + nr2b*r2b
	State.Set(nm, int(z), int(y), int(x), int(EWNuMag), int(cur))
	State.Set(lm, int(z), int(y), int(x), int(EWELMag), int(cur))
	State.Set(rm, int(z), int(y), int(x), int(EWERMag), int(cur))
	State.Set(lm+rm, int(z), int(y), int(x), int(EWEMag), int(cur))
}

func ElectroweakDampKernel(i uint32) { //gosl:kernel
	ctx := GetCtx(0)
	var x, y, z int32
	face := ctx.EdgeCoords(i, &x, &y, &z)
	if face < 0 {
		return
	}
	sz := ctx.SizePlus1() // exclude updating on edges
	cur := ctx.CurState
	prv := ctx.PrevState()
	csq := Params[0].CSq

	// the gauge fields: B, W1, W2, W3, each four potentials then four
	// velocities, all damping toward zero as Maxwell's do
	for g := range 4 {
		base := int32(EWB0s) + int32(g)*8
		for k := range 4 {
			vr := base + int32(k)
			pp := State.Value(int(z), int(y), int(x), int(vr), int(prv))
			f := LaplacianEdge19(x, y, z, sz.X, sz.Y, sz.Z, vr, prv, pp)
			v := csq * f // key damp: no +=
			State.Set(v, int(z), int(y), int(x), int(vr+4), int(cur))
			State.Set(pp+v, int(z), int(y), int(x), int(vr), int(cur))
		}
	}

	// the Higgs is COPIED from the nearest interior cell, not damped.
	//
	// Damping it toward zero is wrong twice over. Its vacuum is |Phi| =
	// HiggsV, so zero is a wall of restored symmetry -- and a domain wall
	// radiates, which is the opposite of what a boundary is for. And which way
	// the doublet points in SU(2) is a gauge choice, so pinning a direction
	// there is a gauge transformation with a gradient, which is a current.
	//
	// Copying is blind to both: it carries whatever magnitude and whatever
	// direction the interior has, so a uniform vacuum stays exactly uniform
	// and above TempCrit, where HiggsV falls to zero, it damps to zero on its
	// own with no special case. It is only zeroth-order open, so a Higgs wave
	// arriving here is not fully absorbed; the gauge fields, which is what
	// most configs are about, get the real treatment above.
	var ix, iy, iz int32
	ctx.EdgeInward(x, y, z, &ix, &iy, &iz)
	for k := range 9 { // the four components, their four velocities, and Hmag
		vr := int32(EWHsCa) + int32(k)
		State.Set(State.Value(int(iz), int(iy), int(ix), int(vr), int(cur)), int(z), int(y), int(x), int(vr), int(cur))
		State.Set(State.Value(int(iz), int(iy), int(ix), int(vr), int(prv)), int(z), int(y), int(x), int(vr), int(prv))
	}
	// The leptons are FIRST order, so Sommerfeld damping has nothing to leave
	// out: they get the open halo of EdgesOpenKernel instead, which is the
	// same copy-from-inward, plus the absorbing layer EWFermionKernel applies
	// in the interior. Done here rather than by running that kernel as well,
	// because it would fight this one over the gauge edge cells.
	for k := range 16 { // three spinors, then the four magnitudes
		vr := int32(EWNu1a) + int32(k)
		State.Set(State.Value(int(iz), int(iy), int(ix), int(vr), int(cur)), int(z), int(y), int(x), int(vr), int(cur))
		State.Set(State.Value(int(iz), int(iy), int(ix), int(vr), int(prv)), int(z), int(y), int(x), int(vr), int(prv))
	}
}

//gosl:end

func (ss *Sim) ElectroweakConfig() {
	ParamsShouldDisplay = ElectroweakParamFields
	ConfigShouldDisplay = ElectroweakConfigFields
	ss.StateVars = EWStatesN
	ss.initFuncs = ElectroweakConfigs
	ss.InitFunc = HiggsBroken
	ss.ElectroweakStats()
	ss.Config.Wavelength = 16
	ss.Config.PacketWidth = 1.5 * ss.Config.Wavelength
	ss.eqViewInitFunc = ElectroweakViewAll
}

// ElectroweakViewAll configures the View to display Electroweak values
func ElectroweakViewAll(view *View) {
	view.Panels[0].Var = EWHs0a
	view.Panels[1].Var = AYs // the transverse component: A0s is zero for a pulse
	view.Panels[2].Var = EWBYs
	view.Panels[3].Var = EWW3Ys
}

// ElectroweakWViewAll configures the View to display Electroweak W collision values
func ElectroweakWViewAll(view *View) {
	view.Panels[0].Var = EWHs0a
	view.Panels[1].Var = EWZX
	view.Panels[2].Var = EWW3Xs
	view.Panels[3].Var = EWW1Ys
}

var (
	// ElectroweakParamFields determines which Parameters fields to display.
	ElectroweakParamFields = []string{"Edges", "Energy", "C", "Hbar", "Mass", "A0NoWave", "E", "Mu0", "SelfField", "EM", "HiggsMu", "HiggsLambda", "Temp", "ThermalC", "GW", "GpW", "YangMills", "Boris", "TempCrit", "HiggsV", "MW", "MZ", "YukawaE", "MassE"}

	// ElectroweakConfigFields determines which additional Config fields to display.
	ElectroweakConfigFields = []string{}
)

//////// stats

// ElectroweakStats adds the stats plotted over time in the GUI. Each one is a
// full pass over the state, so at 100^3 they are not free: raise
// Config.ViewInterval if the run drags.
func (ss *Sim) ElectroweakStats() {
	ss.AddStat(ss.StatStep())
	ss.AddStat(ss.StatMean(EWHmag)) // directly comparable to v^2
	ss.AddStat(ss.StatSum(EWHV))
	// the pulse configs: photon vs Z, and the two fields they are mixed from.
	// The photon runs at ~c and the Z visibly slower, while W^3 and B each show
	// whichever of the two they currently carry.
	ss.AddStat(ss.StatGroupVel(math32.X, AYs, EWZY, EWBYs, EWW3Ys))
	ss.AddStat(ss.StatWidth(math32.Z, AYs, EWZY))
	// W collision: W^3 generated out of nothing by the non-abelian coupling.
	ss.AddStat(ss.StatSumSq(EWW3SqStat, EWW30s, EWW3Xs, EWW3Ys, EWW3Zs))
	// what a Z packet does to the condensate it travels through.
	ss.AddStat(ss.StatWeightedMean(EWHmagZStat, EWHmag, EWZY))
	// the leptons: the neutrino runs at c and the electron does not, and the
	// only difference between them is which half of the doublet they sit in
	ss.AddStat(ss.StatSum(EWNuMag))
	ss.AddStat(ss.StatSum(EWEMag))
	ss.AddStat(ss.StatSum(EWELMag))
	ss.AddStat(ss.StatSum(EWERMag))
	ss.AddStat(ss.StatGroupVelMag(math32.X, EWNuMag, EWEMag))
}

// Stat names that are not built from a variable and a dimension.
const (
	// EWW3SqStat is the summed squares of all four W^3 components.
	EWW3SqStat = "W3Sq"

	// EWHmagZStat is |Phi|^2 weighted by the local Z intensity.
	EWHmagZStat = "HmagZ"
)

//////// configurations

var ElectroweakConfigs = []InitFunc{
	InitFunc{Name: "Higgs Broken", Doc: "Broken symmetry with Higgs field (Hs0a) at vacuum expectation value", Func: HiggsBroken, Current: true},
	InitFunc{Name: "Higgs Symmetric", Doc: "Higgs starts at zero plus noise and falls off the top of the Mexican hat; watch Hmag climb to v^2 and ring", Func: HiggsSymmetric},
	InitFunc{Name: "EM Pulse", Doc: "Transverse EM pulse travelling along X at exactly c; watch AYs", Func: EMPulse},
	InitFunc{Name: "Z Pulse", Doc: "Z boson pulse along X at about 0.75 c, slower than light because the condensate gives it mass; watch ZY", Func: ZPulse},
	InitFunc{Name: "Lepton Packets", Doc: "A neutrino and an electron as the same wave in the two halves of one doublet: the Higgs gives one of them a mass and cannot touch the other", Func: LeptonPackets},
	InitFunc{Name: "W Collision", Doc: "Two W packets cross and generate longitudinal W^3 where they overlap: the non-abelian eps^abc coupling in action; watch W3Xs and ZX", Func: WCollision},
}

//////// initialization helpers

// ewDemoScale raises the electroweak scale so m_W and m_Z are comparable to a
// packet a few tens of cubes long. At the SM scale the boson Compton
// wavelengths are ~22 cubes, so a visible packet is far above threshold and the
// Z would run at 0.97 c. g and g' are untouched, so the mixing angle and
// m_W / m_Z stay physical.
func ewDemoScale(ss *Sim, mu float32) {
	ss.Params.HiggsMu = mu
	ss.Params.Update()
}

// ewVZero returns the zero-temperature vacuum value, mu/sqrt(lambda): still
// the natural amplitude scale when Temp has driven HiggsV to zero.
func ewVZero(ss *Sim) float32 {
	p := ss.Params
	if p.HiggsLambda <= 0 {
		return 0
	}
	return p.HiggsMu / math32.Sqrt(p.HiggsLambda)
}

// HiggsBroken initializes the vacuum is <Phi> = (0, v/sqrt2)^T, i.e.
// the NEUTRAL (lower) component holds the VEV, with magnitude
// v = mu/sqrt(lambda) -- not mu. Putting it
// in the charged component instead would leave Q = T^3 + Y broken
// and give the photon a mass.
func HiggsBroken(ss *Sim) {
	ss.Fill(EWHs0a, Both, ss.Params.HiggsV)
}

// EWDemoYukawa is the Yukawa coupling LeptonPackets sets, in place of the real
// 2.9e-6 that Parameters.Defaults carries. It puts the electron's inverse
// Compton length near the carrier wavenumber at the default wavelength, which
// is the one regime where a mass is visible: much lighter and the electron is
// a neutrino, much heavier and it does not move.
//
// It is absurd as a Yukawa -- larger than the top quark's -- and that IS the
// physical content. The electron is light because its coupling to the Higgs is
// tiny, not because anything else about it is small, and the only way to see
// the mechanism work on a lattice is to wind that one number up.
const EWDemoYukawa float32 = 8

// LeptonPackets puts a neutrino and an electron in the broken vacuum, side by
// side, as the same wave in different halves of the same doublet.
//
// Both start purely left-handed and identical. The neutrino stays that way and
// travels at c: the Yukawa term needs a nu_R to couple it to and there isn't
// one. The electron does not, because the lower component of the doublet is
// the one the Higgs talks to -- it picks up a right-handed half within a few
// steps and settles into a packet that is visibly slower.
//
// Nothing was set differently between the two. There is no mass parameter, no
// charge parameter, and no switch. The condensate is doing it.
func LeptonPackets(ss *Sim) {
	HiggsBroken(ss)
	p := ss.Params
	p.YukawaE = EWDemoYukawa
	p.Update()
	a := ss.Config.Amplitude
	wl := ss.Config.Wavelength

	// the neutrino: massless, so nothing joins the chiralities
	omn, vgn := ss.ChiralDispersion(wl, 0)
	ss.ChiralSlab(EWNu1a, math32.X, -1, a, omn, vgn, 0, 0)

	// the electron: both halves at one helicity, in the ratio a positive
	// energy state has, exactly as ElectronPacket does for the free equation
	om0 := p.C * p.MassE
	ome, vge := ss.ChiralDispersion(wl, om0)
	ck := p.C * math32.Sin(TwoPi/wl)
	rr := float32(0)
	if om0 > 0 {
		rr = (ome - ck) / om0
	}
	ss.ChiralSlab(EWEL1a, math32.X, -1, a, ome, vge, 0, 0)
	ss.ChiralSlab(EWER1a, math32.X, -1, a*rr, ome, vge, 0, 0)
}

// HiggsSymmetric starts every Higgs component at zero plus a whisper of noise,
// and lets the field fall off the top of the Mexican hat into the broken vacuum.
// Any deviation of \Phi off of 0 is enough to knock it off of the unstable maximum.
//
// Adjusting Temp around TempCrit changes the shape of the potential: if above
// TempCrit then it is symmetric and the zero remains stable, not unstable.
//
// EWHmag climbs from 0 to v^2, but overshoots and rings rather than settling,
// because nothing here dissipates. In the early universe Hubble
// expansion drained it, and there is no equivalent in a fixed box.
// Note: it takes a while, around 700 time steps at default params.
func HiggsSymmetric(ss *Sim) {
	amp := 0.02 * ewVZero(ss)
	ss.SmoothNoise(EWHsCa, amp, 6)
	ss.SmoothNoise(EWHsCb, amp, 6)
	ss.SmoothNoise(EWHs0a, amp, 6)
	ss.SmoothNoise(EWHs0b, amp, 6)
}

// EMPulse sends a transverse electromagnetic pulse along X at exactly the
// speed of light.
//
// The packet is written in the PHYSICAL basis: the photon is the combination
// sin(theta_W) W^3 + cos(theta_W) B, the direction that Q = T^3 + Y annihilates,
// so the condensate gives it no mass and it moves at c. Watch AYs.
func EMPulse(ss *Sim) {
	HiggsBroken(ss)
	p := ss.Params
	wl := ss.Config.Wavelength
	om := ss.LatticeFreq(wl, 0) // massless
	cx := float32(ss.Config.Size.X) * 0.2
	// the weights are the photon direction itself; Config.Amplitude sets the size
	ss.CarrierPacketConfig(EWW3Ys, EWW3Yv, math32.X, cx, p.SinThetaW, 1, om, 0)
	ss.CarrierPacketConfig(EWBYs, EWBYv, math32.X, cx, p.CosThetaW, 1, om, 0)
}

// ZPulse sends a Z boson pulse along X, which travels SLOWER than light.
// Because Z is cos(theta_W) W^3 - sin(theta_W) B, that direction does not
// annihilate the vacuum, so it takes mass m_Z from the condensate and the
// packet moves at the group velocity:
//
//	v_g = c khat / sqrt(khat^2 + m_Z^2)
//
// which would be about 0.70 c here, vs 0.98 c for the photon. Watch ZY.
// With the default [Config.Amplitude] of 1, it melts the condensate it
// passes through to about a third of vacuum, and a lighter Z travels faster.
//
// Note this raises the Higgs scale, for the reason given in ewDemoScale.
func ZPulse(ss *Sim) {
	ewDemoScale(ss, 0.388)
	HiggsBroken(ss)
	p := ss.Params
	wl := ss.Config.Wavelength
	om := ss.LatticeFreq(wl, p.MZ)
	cx := float32(ss.Config.Size.X) * 0.2
	// the weights are the Z direction itself; Config.Amplitude sets the size
	ss.CarrierPacketConfig(EWW3Ys, EWW3Yv, math32.X, cx, p.CosThetaW, 1, om, 0)
	ss.CarrierPacketConfig(EWBYs, EWBYv, math32.X, cx, -p.SinThetaW, 1, om, 0)
}

// WCollision fires two W packets at each other. They do not bounce -- gauge
// fields pass through each other -- but the Yang-Mills eps^abc W^b W^c term
// means a W^1 and a W^2 generate W^3 where they overlap, out of nothing. Turn
// off Params.YangMills and they cross without a trace: that is the whole
// difference between SU(2) and three copies of U(1).
//
// Watch W3Xs, and ZX built from it. X, not Y: both packets are polarised along
// Y and travel along X, so W^{b mu} d_mu vanishes and the transport term is
// silent. The surviving transpose term sources the LONGITUDINAL W^3_x, which
// for a massive vector is physical -- the eaten Goldstone. A single packet
// generates exactly zero. With wrapped edges the pair re-collides every lap,
// so the signal accumulates rather than peaking.
//
// The envelope width is set here rather than from Config.PacketWidth: the
// packets start 40% of the box apart, and the 1.5 wl default has them already
// overlapping at half amplitude. On a 100-wide box 1.5 wl gives 50% overlap at
// t=0, 1.2 wl 34%, 0.75 wl 6% -- the first that looks like a collision. The
// large amplitude pays for that: the source is quadratic in W, so 0.1 v ->
// 0.25 v wins back 6x of the 260x the narrower envelope costs.
func WCollision(ss *Sim) {
	ewDemoScale(ss, 0.388)
	HiggsBroken(ss)
	p := ss.Params
	wl := ss.Config.Wavelength
	om := ss.LatticeFreq(wl, p.MW)
	amp := 0.25 * p.HiggsV * ss.Config.Amplitude
	xl := float32(ss.Config.Size.X)
	ss.CarrierPacket(EWW1Ys, EWW1Yv, math32.X, xl*0.3, wl, 0.75*wl, amp, 1, om, 0)
	ss.CarrierPacket(EWW2Ys, EWW2Yv, math32.X, xl*0.7, wl, 0.75*wl, amp, -1, om, 0)
	if ss.GUI.View != nil {
		ss.eqViewInitFunc = ElectroweakWViewAll
		ss.callViewInit(ss.GUI.View)
	}
}
